import{_ as e,o as a,c as _,ag as p}from"./chunks/framework.DaAXJYxM.js";const u=JSON.parse('{"title":"第56章 一张照片","description":"","frontmatter":{},"headers":[],"relativePath":"第56章_一张照片.md","filePath":"第56章_一张照片.md"}'),o={name:"第56章_一张照片.md"};function r(n,t,s,c,i,d){return a(),_("div",null,[...t[0]||(t[0]=[p('<h1 id="第56章-一张照片" tabindex="-1">第56章 一张照片 <a class="header-anchor" href="#第56章-一张照片" aria-label="Permalink to &quot;第56章 一张照片&quot;">​</a></h1><p>她下午两点五十的飞机。我没有去。</p><p>有三个原因，我按顺序说。第一个原因，那张票要两百六十块，我身上有一百四，仓库还没结钱。第二个原因，她说过别去，她原话是：你别来，来了我反而要哭，我哭完我妈要问。第三个原因我没跟任何人讲过：我怕我去了，她会回头看我。她如果不回头，我就还有&quot;她走了&quot;这件事可以过。她要是回头了，我这辈子剩下的每一天都在那个回头上。</p><p>那天上午我在家把仓库的架子加固了一次。我从学校后面捡了两块板回来，压在箱子底下。我家那面墙我拿纸垫了一层，怕潮。我妈在客厅看电视，声音很大。我一个人蹲在房间里，拿螺丝刀拧那两块板，拧了很久。十二点多我给她发了一句：收拾好了吗。她说，在吃饭。我说，吃的什么。她说，饺子。她说，我妈包的，我平时不吃韭菜，今天吃了三个。我说，那挺好。她说，一点都不好，撑死了。</p><p>一点二十，她上线了一次，发了一张图。机场的落地玻璃，外面是一架飞机的尾巴，红色，机身上有一块被太阳照得很亮。她说，起飞前给你看一下。我说，好。她说，我要关机了。我说，嗯。她说，你又嗯。她说，你今天就一个字都不肯多打吗。我说，你关机了我也在打，你看不见。</p><p>她没回。</p><p>两点十四，屏幕上最后一条，是她发的：到了我给你发定位。然后那个号安静了。我看表，我那时候算的是：两点五十起飞，飞十三小时，落地是那边凌晨一点多，这边早上八点。所以我这边早上八点之前，她不会有消息。而我这一晚要做的只有一件事，就是等那张定位。我把手机放在桌上，插着充电，屏幕朝上。我先睡了半个小时，醒了没有。我起来上厕所得知我妈还没睡，她在客厅把电视声音关小了。三点没有，四点没有。四点半我做了一件很丢人的事：我打开那张照片，重新看。我看那架红色的飞机尾巴，看了很久。我看到第五遍的时候，发现了一件事：那块被太阳照得很亮的地方，不是机身，那是玻璃上的反光。反光里有一个人，一只手举着手机，另一只手抓着一个背包的带子，人侧着站。她把自己拍进了一张机场照片的反光里，而且她大概自己都没发现。我把那张图放大，放到糊成一片。我看到的是：她那天穿的应该是那件洗得发白的短袖，外面套件长袖。我看到的是她的头发比前面长了一点。我看到的是她在登机口旁边站着，那一带没有别人。我把手机放下，坐在黑屋子里。</p><p>那天夜里我明白过来一件事：她那天说&quot;给你看一下&quot;，她给我看的不是飞机。她是在不能回头的那种情况下，把一张她自己在里面的东西发给我了。而她多半是事后才看见的，也可能一辈子不会再看这张图。早上七点五十八，我手机响了，不是她，是我们班那个男生，他问他高中学的某科笔记在不在我这儿。我说在，我给你拍。我趴在床上给他拍笔记，拍了四十多页。拍完我八点二十看手机，没有。八点四十没有。中午十二点，我给我妈说，我出去一下。我妈说，你去哪儿。我说，驿站。我说，仓库有三个包裹要发。我妈在围裙上擦手，抬头看了我一下，说，今天？我说，今天。她说，今天你别跑了。我说，为什么。她没答。她走到阳台上收了一件衣服，抱在怀里，站在阳台门口，说，那个小姑娘今天走？我说，嗯。她说，你怎么知道是今天。我说，她跟我说的。我妈把衣服换了个手，说，那你在家待着吧。她说，你这时候出去干什么。我说，发东西。她说，什么东西不能明天发。我站在那里，看着我妈。我妈那辈子说话不重，但她每句话都是收尾的。我说，那我明天发。我把门带上，回房间，把三个包裹拆出来，重新放回架子上。</p><p>那天下午我到四点没出房间。四点我把手机充上电，挪到枕头边。那天晚上她还是没来。夜里两点我下一次楼，我们单元门的灯是声控的，拍一下亮二十秒。我下楼是因为屋里太热，我拿不住手机。我在楼下那个铁凳上坐了七八分钟，把那张照片又打开了一遍。那天夜里我头一回发现一件事：那块反光里只有她，反光里那一排座位、地上的影子、行李车，都没有人。登机口那一带是空的。她把一张没有别人的地方拍下来发给我。我上去的时候，门口有一个碗。我妈把面放在我家门口的地上，碗上面扣了一个盘子挡灰。面已经涨开了。我端进去，坐在桌上把它吃完。汤是凉的，底下还剩一点辣油，凝成了小片。我没有敲我爸妈的门。那天夜里我把面吃了，把碗洗了，回到房里，继续看手机。三点四十一分，屏幕上亮了一下，不是她，是一个陌生号的验证码。</p><p>那天早上我把碗放回厨房，我妈已经在擦桌子。她说，面吃了？我说，吃了。她说，凉不凉。我说，不凉。她说，不凉你吃得那么快。她没抬头，她接了一句：你坐着吧，今天别走。第二天中午，一条。她说，昨天落地以后手机没信号，卡没开。她说，我今天去办了。她说，这里超市八点关门，超市八点关门是什么概念你知道吗。她说，我今天买了个锅，很贵。她说，我妈说贵就贵吧，你自己过日子。我看着那四行字，忽然发现自己昨天晚上在等她。我算错的那一个小时，我到现在也没搞清是哪里算错。我把这件事记在本子上，我写：她落地那天，我在算她的时间，我算错了一个小时。我想了想，在下面又加了一行：那张照片里，只有我看见了她。</p>',10)])])}const m=e(o,[["render",r]]);export{u as __pageData,m as default};
